DROP TABLE IF EXISTS `practice_session`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `practice_session` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `student_id` bigint NOT NULL,
  `paper_version_id` bigint NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'IN_PROGRESS',
  `total_score` int DEFAULT NULL,
  `submission_key` varchar(100) DEFAULT NULL,
  `submission_result_json` text,
  `entity_version` bigint NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `submitted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_practice_paper` (`paper_version_id`),
  KEY `idx_practice_session_student_created_at` (`student_id`,`created_at`),
  CONSTRAINT `fk_practice_paper` FOREIGN KEY (`paper_version_id`) REFERENCES `paper_version` (`id`),
  CONSTRAINT `fk_practice_student` FOREIGN KEY (`student_id`) REFERENCES `user_account` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
